def shift(grid, delta):
    result = grid[:]
    for row in result:
        for i in range(len(row)):
            row[i] += delta
    return result

task.model:
def shift(grid, delta):
    result = []
    for row in grid:
        changed = []
        for value in row:
            changed.append(value + delta)
        result.append(changed)
    return result

